// Provenance tag for any shown value: where does this number / threshold come
// from? Border style + icon + Turkish word (never colour alone):
//   GERÇEK    solid   — real public data (NASA OSDR, PhysioNet, NASA DONKI)
//   STANDART  double  — threshold cited from NASA-STD-3001
//   DEMO      dashed  — demo threshold, evidence class F, awaiting expert review
//   SENTETİK  dotted  — generated by a demo scenario, not a measurement
//   ELLE      solid   — typed in by a user (manual entry)
import type { HTMLAttributes } from 'react';
import { Icon, type IconName } from './icons';

export type SourceKind = 'REAL' | 'STANDARD' | 'DEMO' | 'SYNTHETIC' | 'MANUAL';

export const SOURCE_META: Record<SourceKind, { label: string; icon: IconName; title: string }> = {
  REAL: {
    label: 'GERÇEK',
    icon: 'satellite',
    title: 'Gerçek kamu verisi (NASA OSDR, PhysioNet veya NASA DONKI kaydı); canlı sensör değil.',
  },
  STANDARD: {
    label: 'STANDART',
    icon: 'check',
    title: 'Eşik NASA-STD-3001 standardından alındı (kaynaklı kural).',
  },
  DEMO: {
    label: 'DEMO',
    icon: 'flask',
    title: 'DEMO eşik (kanıt sınıfı F): uçuş tıbbı uzmanı doğrulaması bekliyor.',
  },
  SYNTHETIC: {
    label: 'SENTETİK',
    icon: 'grid',
    title: 'Demo senaryosunun ürettiği sentetik veri; gerçek ölçüm değil.',
  },
  MANUAL: {
    label: 'ELLE',
    icon: 'user',
    title: 'Kullanıcı tarafından elle girildi.',
  },
};

export interface SourceBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  kind: SourceKind;
  /** Short origin shown after the label, e.g. "PhysioNet", "NASA-STD-3001". */
  detail?: string | null;
  size?: 'xs' | 'sm';
}

export function SourceBadge({ kind, detail, size = 'sm', title, className, ...rest }: SourceBadgeProps) {
  const m = SOURCE_META[kind];
  return (
    <span
      {...rest}
      className={`ui-src ui-src--${kind.toLowerCase()} ui-src--${size}${className ? ` ${className}` : ''}`}
      title={title ?? (detail ? `${m.title} Kaynak: ${detail}.` : m.title)}
    >
      <Icon name={m.icon} size={size === 'xs' ? 10 : 12} />
      <span className="ui-src__label">{m.label}</span>
      {detail && <span className="ui-src__detail">{detail}</span>}
    </span>
  );
}

/* ------------------------------------------------- derive kind from data */

/** Threshold provenance of a rule / action card. null = nothing to claim. */
export function ruleSource(r: {
  validation_status?: string | null;
  evidence_level?: string | null;
  source?: string | null;
  references?: { label: string }[] | null;
} | null | undefined): { kind: SourceKind; detail: string | null } | null {
  if (!r?.validation_status) return null;
  if (r.validation_status.startsWith('DEMO')) return { kind: 'DEMO', detail: r.evidence_level ? `kanıt ${r.evidence_level}` : null };
  if (r.validation_status === 'APPROVED') {
    const text = [r.source ?? '', ...(r.references ?? []).map((x) => x.label)].join(' ');
    // Only the cabin CO2 rule is APPROVED today and it cites NASA-STD-3001.
    if (/NASA-STD-3001/i.test(text) || !text.trim()) return { kind: 'STANDARD', detail: 'NASA-STD-3001' };
    return { kind: 'STANDARD', detail: null };
  }
  return null;
}

/** Measurement provenance. The series endpoint carries no source_type, so the
 * mission's scenario id is the evidence: scenario missions are SYNTHETIC.
 * Without a scenario we do not guess (null = no badge). */
export function measurementSource(scenarioId: string | null | undefined): SourceKind | null {
  return scenarioId ? 'SYNTHETIC' : null;
}

/** Lab provenance from LabResult.source_type. */
export function labSource(sourceType: string | null | undefined): { kind: SourceKind; detail: string | null } | null {
  if (sourceType === 'OSDR') return { kind: 'REAL', detail: 'NASA OSDR' };
  if (sourceType === 'SYNTHETIC') return { kind: 'SYNTHETIC', detail: null };
  if (sourceType === 'MANUAL') return { kind: 'MANUAL', detail: null };
  return null;
}
